import './App.css';

const iceCreamArray = [
  {
    title: "Ice Cream Shop #1"
  },
  {
    title: "Ice Cream Shop #2"
  },
  {
    title: "Ice Cream Shop #3"
  }
]

function IceCreamShopHeader(){
  return(
    <div>
       <h1>Ice Cream Shop</h1>
        <h2>Welcome to the best ice cream shop in the world!</h2>
      </div>
  )
}

function App() {
  return (
    <div className="App">
      <IceCreamShopHeader/>
      <IceCreamShopHeader/>
      <IceCreamShopHeader/>
    </div>
  );
}

export default App;
